package canteen;

import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;import java.time.LocalDate;import java.io.*;

public class ReportFrame extends JFrame {
 private final String role;private JLabel ordersLabel,revenueLabel,todayLabel,averageLabel;private JTable table;private DefaultTableModel model;private JTextField fromField,toField;private JTextArea paymentSummary;
 public ReportFrame(){this("ADMIN");}
 public ReportFrame(String role){this.role=role;if(!AuditLog.isAdmin(role)){AuditLog.requireAdmin(null,role);dispose();return;}AppStyle.apply();AppStyle.setWindowIcon(this);setTitle("PIET | Sales Reports");setSize(1120,720);setMinimumSize(new Dimension(900,600));setLocationRelativeTo(null);JPanel p=AppStyle.page("Sales reports & analytics");JPanel filter=new JPanel(new FlowLayout(FlowLayout.LEFT,10,5));filter.setOpaque(false);fromField=new JTextField(LocalDate.now().withDayOfMonth(1).toString(),10);toField=new JTextField(LocalDate.now().toString(),10);JButton apply=AppStyle.button("Apply date range",AppStyle.BLUE),export=AppStyle.button("Export CSV",new Color(32,145,118)),print=AppStyle.button("Print report",AppStyle.NAVY);filter.add(new JLabel("From (YYYY-MM-DD)"));filter.add(fromField);filter.add(new JLabel("To (YYYY-MM-DD)"));filter.add(toField);filter.add(apply);filter.add(export);filter.add(print);
  JPanel cards=new JPanel(new GridLayout(1,4,12,12));cards.setOpaque(false);ordersLabel=stat(cards,"COMPLETED ORDERS","0",AppStyle.BLUE);revenueLabel=stat(cards,"NET SALES","₹ 0.00",new Color(32,145,118));todayLabel=stat(cards,"DISCOUNTS","₹ 0.00",new Color(200,125,30));averageLabel=stat(cards,"AVERAGE ORDER","₹ 0.00",new Color(126,83,190));model=new DefaultTableModel(new String[]{"Food item","Quantity sold","Item revenue"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);AppStyle.styleTable(table);JPanel body=new JPanel(new BorderLayout(10,10));body.setOpaque(false);body.add(cards,BorderLayout.NORTH);JPanel sales=AppStyle.card();sales.add(new JLabel("Best-selling food items (completed orders only)"),BorderLayout.NORTH);sales.add(new JScrollPane(table),BorderLayout.CENTER);paymentSummary=new JTextArea(3,30);paymentSummary.setEditable(false);paymentSummary.setFont(new Font("Segoe UI",Font.PLAIN,12));paymentSummary.setBackground(new Color(248,250,254));sales.add(new JScrollPane(paymentSummary),BorderLayout.SOUTH);body.add(sales,BorderLayout.CENTER);JPanel north=new JPanel(new BorderLayout(8,8));north.setOpaque(false);north.add(filter,BorderLayout.NORTH);north.add(body,BorderLayout.CENTER);p.add(north,BorderLayout.CENTER);add(p);apply.addActionListener(e->loadReport());export.addActionListener(e->exportCsv());print.addActionListener(e->{try{table.print();}catch(Exception ex){JOptionPane.showMessageDialog(this,"Print failed: "+ex.getMessage());}});loadReport();}
 private JLabel stat(JPanel parent,String title,String value,Color color){JPanel card=AppStyle.card();JPanel strip=new JPanel();strip.setBackground(color);strip.setPreferredSize(new Dimension(5,10));card.add(strip,BorderLayout.WEST);JPanel b=new JPanel(new GridLayout(2,1,0,8));b.setOpaque(false);JLabel t=new JLabel(title);t.setForeground(AppStyle.MUTED);t.setFont(new Font("Segoe UI",Font.BOLD,11));JLabel v=new JLabel(value);v.setForeground(AppStyle.NAVY);v.setFont(new Font("Segoe UI",Font.BOLD,20));b.add(t);b.add(v);card.add(b,BorderLayout.CENTER);parent.add(card);return v;}
 private boolean validRange(){try{LocalDate a=LocalDate.parse(fromField.getText().trim()),b=LocalDate.parse(toField.getText().trim());if(b.isBefore(a))throw new IllegalArgumentException();return true;}catch(Exception e){JOptionPane.showMessageDialog(this,"Enter valid dates in YYYY-MM-DD format; end date must not precede start date.");return false;}}
 private void loadReport(){if(!validRange())return;String from=fromField.getText().trim(),to=toField.getText().trim();String summary="SELECT COUNT(*) orders_count,COALESCE(SUM(final_total),0) sales,COALESCE(SUM(discount),0) discounts,COALESCE(AVG(final_total),0) avg_order FROM orders WHERE status='COMPLETED' AND DATE(order_date) BETWEEN ? AND ?";String best="SELECT oi.item_name,SUM(oi.quantity) qty,SUM(oi.line_total) revenue FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE o.status='COMPLETED' AND DATE(o.order_date) BETWEEN ? AND ? GROUP BY oi.item_name ORDER BY qty DESC,revenue DESC";model.setRowCount(0);try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(summary)){s.setString(1,from);s.setString(2,to);try(ResultSet r=s.executeQuery()){if(r.next()){ordersLabel.setText(r.getString("orders_count"));revenueLabel.setText(String.format("₹ %.2f",r.getDouble("sales")));todayLabel.setText(String.format("₹ %.2f",r.getDouble("discounts")));averageLabel.setText(String.format("₹ %.2f",r.getDouble("avg_order")));}}try(PreparedStatement q=c.prepareStatement(best)){q.setString(1,from);q.setString(2,to);try(ResultSet r=q.executeQuery()){while(r.next())model.addRow(new Object[]{r.getString(1),r.getInt(2),String.format("₹ %.2f",r.getDouble(3))});}}StringBuilder payText=new StringBuilder("Payment method breakdown:  ");try(PreparedStatement q=c.prepareStatement("SELECT payment_method,COUNT(*) n,SUM(final_total) revenue FROM orders WHERE status='COMPLETED' AND DATE(order_date) BETWEEN ? AND ? GROUP BY payment_method ORDER BY revenue DESC")){q.setString(1,from);q.setString(2,to);try(ResultSet r=q.executeQuery()){while(r.next())payText.append(r.getString(1)).append(": ").append(r.getInt(2)).append(" orders / ₹").append(String.format("%.2f",r.getDouble(3))).append("     ");}}paymentSummary.setText(payText.toString());}catch(SQLException e){JOptionPane.showMessageDialog(this,"Could not load reports. Check migration and database connection.\n"+e.getMessage(),"Report error",JOptionPane.ERROR_MESSAGE);}}
 private void exportCsv(){if(!validRange())return;JFileChooser f=new JFileChooser();f.setSelectedFile(new File("piet_sales_report.csv"));if(f.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(PrintWriter w=new PrintWriter(f.getSelectedFile(),"UTF-8")){w.println("Report period,"+fromField.getText()+" to "+toField.getText());w.println("Completed orders,"+ordersLabel.getText());w.println("Net sales,"+revenueLabel.getText());w.println("Discounts,"+todayLabel.getText());w.println("Average order,"+averageLabel.getText());w.println();w.println("Food item,Quantity sold,Item revenue");for(int r=0;r<model.getRowCount();r++)w.println(csv(model.getValueAt(r,0).toString())+","+csv(model.getValueAt(r,1).toString())+","+csv(model.getValueAt(r,2).toString()));AuditLog.record("system","SALES_REPORT_EXPORTED",f.getSelectedFile().getName());JOptionPane.showMessageDialog(this,"CSV report exported.");}catch(Exception e){JOptionPane.showMessageDialog(this,"Export failed: "+e.getMessage());}}
 private String csv(String s){return "\""+s.replace("\"","\"\"")+"\"";}
}
